  if (!hostname.includes("[") && !hostname.includes("]")) return hostname;
  const unbracketed = hostname.slice(1, -1);
  if (
    hostname.startsWith("[") &&
    hostname.endsWith("]") &&
    isIP(unbracketed) === 6
